            width: 28px;
            height: 28px;
            display: flex;
            flex-direction: column;
            justify-content: space-around;
            cursor: pointer;
            padding: 4px 0;
        }

        .menu-btn span {
            display: block;
            width: 100%;
            height: 2px;
            background-color: white;
            border-radius: 2px;
        }

        /* 主内容区域 */
        .main-content {
            margin-top: 50px;
            background-color: white;
            min-height: calc(100vh - 50px);
        }

        /* 用户信息区域 */
        .user-info {
            padding: 10px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .avatar-wrapper {
            position: relative;
        }

        .avatar {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-size: 18px;
            font-weight: bold;
            overflow: hidden;
        }

        .verified-badge {
            position: absolute;
            bottom: -2px;
            right: -2px;
            width: 18px;
            height: 18px;
            background-color: #ff4500;
            border-radius: 50%;
            border: 2px solid white;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10px;
            color: white;
        }

        .user-details {
            flex: 1;
        }

        .username {
            font-size: 14px;
            color: #000;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .pub-time {
            font-size: 12px;
            color: #999;
        }

        .user-meta {
            font-size: 12px;
            color: #a1a3a6;
            line-height: 12px;
            margin-top: 2px;
        }

        /* 文章内容 */
        .article-content {
            padding: 20px 15px;
            font-size: 17px;
            line-height: 1.71;
            color: #333;
            min-height: 1000px;
            /* letter-spacing: 0.5px; */
        }

        .article-content p {
            margin-bottom: 1em;
            text-align: justify;
        }

        /* 图片容器 */
        .article-image {
            width: 100%;
            margin: 20px 0;
        }

        .article-image img {
            width: 100%;
            height: auto;
            display: block;
            border-radius: 8px;
        }

        /* 图片网格布局 - 一行两个 */
        .image-grid {
            display: flex;
            overflow: auto;
            gap: 10px;
            margin-bottom: 10px;
        }

        .image-grid::-webkit-scrollbar {
            display: none;
            height: 0;
        }

        .image-grid img {
            width: 100%;
            height: auto;
            max-height: 300px;
            display: block;
            object-fit: cover;
            border-radius: 4px;
            flex: none;
            max-width: 300px;
        }

        /* 发布信息 */
        .publish-info {
            color: #999;
            font-size: 14px;
        }

        /* 底部导航区域 */
        .bottom-nav {
            background-color: #fafafa;
            border-top: 1px solid #e5e5e5;
            padding: 20px 15px;
        }

        .nav-grid {
            display: grid;
            grid-template-columns: repeat(6, 1fr);
        }

        .nav-item {
            text-align: center;
            color: #666;
            font-size: 15px;
            padding: 8px 5px;
            cursor: pointer;
            transition: color 0.3s;
        }

        .nav-item:hover {
            color: #ff4500;
        }

        /* 底部操作栏 */
        .footer-actions {
            display: flex;
            justify-content: space-around;
            padding: 6px 0;
            background-color: #fafafa;
            /* border-top: 0.5px solid #e5e5e5; */
        }

        .action-btn {
            display: flex;
            flex-direction: column;
            align-items: center;
            color: #666;
            font-size: 14px;
            cursor: pointer;
            transition: color 0.3s;
        }

        .action-btn:hover {
            color: #ff4500;
        }

        .action-label {
            font-size: 13px;
        }

        /* 页脚信息 */
        .footer-info {
            text-align: center;
            padding: 6px 0;
            color: #999;
            font-size: 12px;
            background-color: #fafafa;
        }

        /* 响应式设计 - 平板 */
        @media screen and (min-width: 768px) {
            .main-content {
                max-width: 750px;
                margin-left: auto;
                margin-right: auto;
                box-shadow: 0 0 20px rgba(0, 0, 0, 0.1);
            }

            .header {
                max-width: 750px;
                margin: auto;
            }

            .article-content {
                font-size: 17px;
                padding: 25px 20px;
            }

            .nav-grid {
                grid-template-columns: repeat(6, 1fr);
            }
        }

        /* 响应式设计 - PC */
        @media screen and (min-width: 1024px) {
            .main-content {
                max-width: 900px;
            }

            .header {
                max-width: 900px;
                height: 60px;
            }

            .main-content {
                margin-top: 60px;
            }

            .logo {
                width: 45px;
                height: 45px;
                font-size: 16px;
            }

            .site-name {
                font-size: 24px;
            }

            .article-content {
                font-size: 19px;
                padding: 30px 40px;
                line-height: 2;
            }

            .user-info {
                padding: 25px 40px;
            }

            .avatar {
                width: 60px;
                height: 60px;
                font-size: 22px;
            }

            .verified-badge {
                width: 20px;
                height: 20px;
                font-size: 11px;
            }

            .username {
                font-size: 18px;
            }

            .nav-grid {
                grid-template-columns: repeat(6, 1fr);
            }

            .nav-item {
                font-size: 16px;
                padding: 10px 8px;
            }

            .publish-info {
                font-size: 15px;
            }
        }

        /* 超大屏幕 */
        @media screen and (min-width: 1440px) {
            .main-content {
                max-width: 1000px;
            }

            .header {
                max-width: 1000px;
            }

            .article-content {
                font-size: 20px;
                padding: 35px 50px;
            }
        }

        /* 小屏幕优化 */
        @media screen and (max-width: 375px) {
            .site-name {
                font-size: 18px;
            }

            .article-content {
                font-size: 16px;
                padding: 0 12px 6px;
            }

            .nav-grid {
                grid-template-columns: repeat(6, 1fr);
            }

            .nav-item {
                font-size: 14px;
                padding: 6px 3px;
            }

            .image-grid img {
                height: 112px;
            }
        }

